import styles from './progress.module.css'

export type ProgressVariant = 'primary' | 'info' | 'success' | 'warning' | 'error'
export type ProgressSize = 'sm' | 'md' | 'lg'

export interface ProgressProps {
  /** 0–100. Omit for indeterminate state. */
  value?: number
  /**
   * Colour of the fill: `primary` (the accent) or a severity tone — `info`, `success`,
   * `warning`, `error`.
   *
   * @defaultValue `primary`
   * @see the component manifest
   */
  variant?: ProgressVariant
  size?: ProgressSize
  /**
   * Invisible accessible name. `ariaLabel` is the catalog convention (see the
   * accessible-name table in `docs/AI-RULES.md`); the DOM spelling `aria-label` is accepted
   * too, so either guess compiles. Two spellings of one idea inside a package was a coin
   * flip on every component.
   */
  ariaLabel?: string
  /**
   * Alias of `ariaLabel` — same invisible accessible name, the other spelling. Not rendered.
   *
   * `ariaLabel` is the catalog convention and stays preferred, but `label` is the guess an
   * adopter makes when they have not read the convention, and an unaccepted guess costs a
   * compile cycle for nothing (2026-08-21 report item 1). Pass either.
   */
  label?: string
  /** DOM-spelled alias of {@link ariaLabel}. */
  'aria-label'?: string
  'aria-describedby'?: string
  className?: string
}

export function Progress({
  value,
  variant = 'primary',
  size = 'md',
  className,
  ariaLabel,
  label,
  ...aria
}: ProgressProps) {
  return (
    <progress
      aria-label={aria['aria-label'] ?? ariaLabel ?? label}
      className={[styles['progress'], className].filter(Boolean).join(' ')}
      data-variant={variant}
      data-size={size}
      value={value}
      max={value !== undefined ? 100 : undefined}
      {...aria}
    />
  )
}

@layer cascivo.component {
  .progress {
    display: block;
    inline-size: 100%;
    appearance: none;
    border: none;
    border-radius: var(--cascivo-radius-full);
    background-color: var(--cascivo-color-surface-2);
    overflow: hidden;
  }

  .progress[data-size='sm'] {
    block-size: 0.25rem;
  }
  .progress[data-size='md'] {
    block-size: 0.5rem;
  }
  .progress[data-size='lg'] {
    block-size: 0.75rem;
  }

  .progress::-webkit-progress-bar {
    background: transparent;
  }
  .progress::-webkit-progress-value {
    background-color: var(--cascivo-progress-color, var(--cascivo-color-accent));
    border-radius: var(--cascivo-radius-full);
    transition: inline-size var(--cascivo-duration-150) var(--cascivo-ease-out);
  }
  .progress::-moz-progress-bar {
    background-color: var(--cascivo-progress-color, var(--cascivo-color-accent));
    border-radius: var(--cascivo-radius-full);
  }

  .progress[data-variant='primary'] {
    --cascivo-progress-color: var(--cascivo-color-primary);
  }
  .progress[data-variant='info'] {
    --cascivo-progress-color: var(--cascivo-color-info);
  }
  .progress[data-variant='success'] {
    --cascivo-progress-color: var(--cascivo-color-success);
  }
  .progress[data-variant='warning'] {
    --cascivo-progress-color: var(--cascivo-color-warning);
  }
  .progress[data-variant='error'] {
    --cascivo-progress-color: var(--cascivo-color-error);
  }

  .progress:indeterminate::-webkit-progress-value {
    animation: cascivo-progress-indeterminate var(--cascivo-duration-loop)
      var(--cascivo-ease-in-out) infinite;
  }
  .progress:indeterminate::-moz-progress-bar {
    animation: cascivo-progress-indeterminate var(--cascivo-duration-loop)
      var(--cascivo-ease-in-out) infinite;
  }

  /* Indicator loop, not a decorative one: it reports that work is happening, so under
     reduced motion it is slowed rather than stopped — a frozen progress bar reads as a
     hung app. Same treatment as Spinner and ProgressBar. */
  @media (prefers-reduced-motion: reduce) {
    .progress:indeterminate::-webkit-progress-value,
    .progress:indeterminate::-moz-progress-bar {
      animation-duration: 4s;
    }
  }

  /* Deliberately NOT the shared `cascivo-progress-sweep`.
     ProgressBar is a div-in-a-div and translates its fill, which keeps the loop off the
     layout path. This component styles the native `<progress>` element, whose
     `::-webkit-progress-value` / `::-moz-progress-bar` pseudo-elements support only a
     narrow, engine-specific property set — `translate` on them is not dependable, while
     sizing them is. So the layout-animating form stays, scoped to the one place the
     platform forces it. Reach for ProgressBar when the loop cost matters. */
  @keyframes cascivo-progress-indeterminate {
    0% {
      inline-size: 0%;
      margin-inline-start: 0;
    }
    50% {
      inline-size: 50%;
      margin-inline-start: 25%;
    }
    100% {
      inline-size: 0%;
      margin-inline-start: 100%;
    }
  }
}
